TempThreadSemaphore_AC		CTempSemaphore;	typedef CMutex::CWhileSynchronized	CWhileSynchronized;	typedef CThreadYielder_AC			CYielder;	//--------------------------------------------------------------------------------	// Constructors, destructor, and assignment	//--------------------------------------------------------------------------------	CThreadMgrThread_AC();		// default constructor	CThreadMgrThread_AC(const CThreadMgrThread_AC& source);		// copy constructor	virtual ~CThreadMgrThread_AC();		// Destructor	//--------------------------------------------------------------------------------	// Running	//--------------------------------------------------------------------------------	virtual CThread_AC* Start();	virtual CThread_AC* Start(ThreadStyle threadStyle);	ThreadOptions GetThreadOptions() const;	operator ThreadID() const { return fThreadID; }	virtual bool IsAlive() const;		// Returns true if the thread or task has not been terminated.	virtual bool IsCurrent() const;		// return true if the thread handle represents the current thread.	static ThreadID Current();	static ThreadTaskRef CurrentTaskRef();	static void Yield();		// Allows other (cooperatively run) threads time to execute.	virtual void YieldTo(ThreadID suggestedThread = kNoThreadID);		// Yields to the suggested thread. The default will yield to this thread, so 		// there's an easy way for other threads to say they want this thread to get time. 	virtual void Suspend();		// Suspends this thread.  Must be called from within the thread (e.g., Run).		// Must be awakened by another thread by calling CThreadRunner_AC's Resume method.			virtual void Resume();		// Resumes the execution of this thread if the thread stopped itself by 		// calling Suspend.			virtual void Join();		// Calls RequestShutdown and blocks the calling thread until the		// thread terminates.					virtual OSStatus GetResult(Duration timeout = 0);	//--------------------------------------------------------------------------------	// Utilities	//--------------------------------------------------------------------------------#if qDebug	#define FailIf(status) DebugFailIf((status),  __FILE__, __LINE__ )	static void DebugFailIf(OSStatus status, const char* inFile, short inLine);#else	static void FailIf(OSStatus status);#endif	static void ProgramBreak(ConstStr255Param msg);		// this accepts a pascal string.	static void ProgramBreak(const char* grievance, ...);		// this accepts printf style arguments.	static void ProgramBreak(const char* format, va_list args);		// this accepts var arguments.	//--------------------------------------------------------------------------------	// Private	//--------------------------------------------------------------------------------private:	static DEFINE_API(void*) EntryPoint(void* parameter);	//--------------------------------------------------------------------------------	// Data	//--------------------------------------------------------------------------------	ThreadTaskRef		fTaskRef;	// Reference to the process in which this thread executes.	ThreadID			fThreadID;	// ID for the thread represented by this context.	bool				fResume;	// Flag used in restarting suspended thread.	void*				fResult;};#endif	// __CThreadMgrThread_AC__